// electron-updater reads the GitHub feed generated by electron-builder.
// Keep this controller independent from Electron's window lifecycle for testing.
function createUpdateService({app,autoUpdater,dialog,publish,beforeInstall=async()=>{},setProgress=()=>{},schedule=setTimeout,repeat=setInterval}) {
  autoUpdater.autoDownload=false;
  autoUpdater.autoInstallOnAppQuit=false;
  autoUpdater.allowPrerelease=false;
  autoUpdater.allowDowngrade=false;
  autoUpdater.on('error',()=>{}); // check/download rejections are handled below.
  autoUpdater.on('download-progress',p=>setProgress(Math.min(1,Math.max(0,(p.percent||0)/100))));
  let busy=false,available=null,downloaded=null,lastOffered=null,lastChecked=0;
  const ready=()=>app.isPackaged&&publish?.provider==='github'&&Boolean(publish.owner&&publish.repo)&&![publish.owner,publish.repo].some(v=>v.startsWith('CONFIGURAR_'));
  async function offerInstall(version) {
    const answer=await dialog.showMessageBox({type:'question',title:'Atualização pronta',message:`SpawnVault ${version} está pronto a instalar.`,detail:'A aplicação vai terminar sessão, reiniciar e instalar a atualização. Guarda as alterações antes de continuar.',buttons:['Mais tarde','Reiniciar e instalar'],defaultId:0,cancelId:0});
    if(answer.response!==1)return {message:`Versão ${version} descarregada. Podes instalá-la em Verificar atualizações.`};
    await beforeInstall();
    autoUpdater.quitAndInstall(false,true);
    return {message:'A reiniciar para instalar a atualização.'};
  }
  async function check({manual=false}={}) {
    if(!ready())return {message:'Atualizações ainda não ativadas. Falta configurar o repositório de distribuição.'};
    if(busy)return {message:'Verificação ou descarga de atualização em curso.'};
    busy=true;lastChecked=Date.now();
    try {
      if(downloaded)return manual?await offerInstall(downloaded):{message:'Atualização descarregada, instalação adiada.'};
      const result=await autoUpdater.checkForUpdates();
      if(!result?.isUpdateAvailable||!result.updateInfo?.version){available=null;return {message:'Já tens a versão mais recente.'};}
      available=result.updateInfo.version;
      if(!manual&&lastOffered===available)return {message:`Versão ${available} disponível.`};
      lastOffered=available;
      const answer=await dialog.showMessageBox({type:'info',title:'Atualização disponível',message:`Está disponível uma nova versão do SpawnVault: ${available}`,detail:`Versão instalada: ${app.getVersion()}. Queres descarregar a atualização? A tua conta e os dados do catálogo são mantidos.`,buttons:['Agora não','Descarregar atualização'],defaultId:0,cancelId:0});
      if(answer.response!==1)return {message:`Versão ${available} disponível. Usa Verificar atualizações quando quiseres atualizar.`};
      await autoUpdater.downloadUpdate();
      downloaded=available;setProgress(-1);
      return await offerInstall(downloaded);
    } catch(error) {
      setProgress(-1);
      if(!manual)lastOffered=null; // Permit retry after transient download failures.
      if(['ERR_UPDATER_NO_PUBLISHED_VERSIONS','ERR_UPDATER_LATEST_VERSION_NOT_FOUND'].includes(error.code))return {message:'Ainda não existe uma versão estável publicada para atualizar.'};
      if(error.code==='ERR_UPDATER_CHANNEL_FILE_NOT_FOUND')return {message:'A versão publicada ainda não tem os ficheiros de atualização necessários. Contacta o administrador.'};
      return {message:`Não foi possível atualizar: ${error.message}`};
    } finally {busy=false;}
  }
  function start() {
    if(!ready())return;
    schedule(()=>check(),15000);
    repeat(()=>check(),4*60*60*1000);
  }
  function resume(){if(ready()&&Date.now()-lastChecked>=10*60*1000)return check();}
  return {check,start,resume,ready};
}
module.exports={createUpdateService};
